using System.Windows;
using System.Windows.Controls;using WindowsGameRuntimeASUSSelfHealing.WinUI.Services;
namespace WindowsGameRuntimeASUSSelfHealing.WinUI.Pages;
public sealed partial class ArchitecturePage:Page{
 private readonly BackendService _backend=App.Services.Backend;private bool _loaded;public ArchitecturePage(){InitializeComponent();Loaded+=async(_,_)=>{if(_loaded)return;_loaded=true;await RefreshAsync();};}
 private async void RefreshButton_Click(object sender,RoutedEventArgs e)=>await RefreshAsync();
 private async Task RefreshAsync(){RefreshButton.IsEnabled=false;Info.Title="后台校验中";try{using var r=await _backend.RunAsync("ARCH",timeout:TimeSpan.FromMinutes(3));if(!r.Success)throw new InvalidOperationException(r.Error);var s=r.Payload.GetProperty("Summary");var lines=new List<string>{$"GUI elevated={s.String("GuiElevation")}",$"Elevated Broker valid={s.String("BrokerValid")}",$"Broker SHA256={s.String("BrokerSHA256")}",$"Build consistency={s.String("BuildConsistency")}",$"Engine={s.String("EngineVersion")} / Build={s.String("BuildId")}",$"Policy mode={s.String("PolicyMode")}",$"External trusted RulePacks={s.String("TrustedExternalRulePacks")}",$"External RulePack auto-repair enabled={s.String("ExternalRuleAutoRepairEnabled")}","","=== RulePacks ==="};foreach(var x in r.Payload.Array("RulePacks")){lines.Add($"{x.String("Kind")} | {x.String("Name")} | signature={x.String("Signature")} | trusted={x.String("Trusted")} | sha256={x.String("SHA256")}");lines.Add("  "+x.String("Detail"));}Output.Text=string.Join("\r\n",lines);var ok=s.String("BrokerValid").Equals("true",StringComparison.OrdinalIgnoreCase)||s.String("BrokerValid")=="True";Info.Title=ok?"安全架构正常":"安全架构需要检查";Info.Message="未知/未签名/发布者指纹不受信的外部 RulePack 不允许授权自动修复。";Info.Severity=ok?InfoBarSeverity.Success:InfoBarSeverity.Warning;}catch(Exception ex){Info.Title="校验失败";Info.Message=ex.Message;Info.Severity=InfoBarSeverity.Error;}finally{RefreshButton.IsEnabled=true;}}
}
